ALTER TABLE public.consultations ADD COLUMN IF NOT EXISTS encryption_metadata JSONB DEFAULT '{}'::JSONB; ALTER TABLE public.prescriptions ADD COLUMN IF NOT EXISTS encryption_metadata JSONB DEFAULT '{}'::JSONB; ALTER TABLE public.vital_signs ADD COLUMN IF NOT EXISTS hospital_id UUID REFERENCES public.hospitals(id); UPDATE public.vital_signs vs SET hospital_id = p.hospital_id FROM public.patients p WHERE p.id = vs.patient_id AND vs.hospital_id IS NULL; CREATE INDEX IF NOT EXISTS vital_signs_hospital_id_idx ON public.vital_signs(hospital_id); DO $do$ BEGIN IF EXISTS (SELECT 1 FROM pg_class WHERE relname = 'vital_signs' AND relrowsecurity = true) THEN DROP POLICY IF EXISTS "Staff can view vital signs" ON public.vital_signs; DROP POLICY IF EXISTS "Staff can insert vital signs" ON public.vital_signs; DROP POLICY IF EXISTS "Staff can update vital signs" ON public.vital_signs; CREATE POLICY "Staff can view vital signs" ON public.vital_signs FOR SELECT USING ( hospital_id IS NOT NULL AND public.user_belongs_to_hospital(auth.uid(), hospital_id) OR EXISTS ( SELECT 1 FROM public.patients p WHERE p.id = patient_id AND public.user_belongs_to_hospital(auth.uid(), p.hospital_id) ) ); CREATE POLICY "Staff can insert vital signs" ON public.vital_signs FOR INSERT WITH CHECK ( hospital_id IS NOT NULL AND public.user_belongs_to_hospital(auth.uid(), hospital_id) OR EXISTS ( SELECT 1 FROM public.patients p WHERE p.id = patient_id AND public.user_belongs_to_hospital(auth.uid(), p.hospital_id) ) ); CREATE POLICY "Staff can update vital signs" ON public.vital_signs FOR UPDATE USING ( hospital_id IS NOT NULL AND public.user_belongs_to_hospital(auth.uid(), hospital_id) OR EXISTS ( SELECT 1 FROM public.patients p WHERE p.id = patient_id AND public.user_belongs_to_hospital(auth.uid(), p.hospital_id) ) ); END IF; END $do$;